// Step 2 & 3: Validate input payload and setup run parameters
const input = $input.first().json;

const ALLOWED_SEVERITIES = new Set(['low', 'medium', 'high', 'critical']);
const ALLOWED_STATUSES = new Set(['submitted', 'under_review', 'assigned', 'in_progress', 'resolved', 'rejected']);
const ALLOWED_DEPARTMENTS = new Set(['traffic', 'safety', 'waste', 'environment', 'water', 'energy', 'general']);
const ALLOWED_SOURCES = new Set(['citizen_complaint', 'simulated_sensor', 'admin']);

// 1. Validate description
const description = input.description ? String(input.description).trim() : '';
if (!description) {
  return [{
    json: {
      is_valid: false,
      error_code: 'VALIDATION_ERROR',
      message: 'The complaint description is required and cannot be empty.',
      event_id: null
    }
  }];
}

// 2. Validate source
const source = input.source || 'citizen_complaint';
if (!ALLOWED_SOURCES.has(source)) {
  return [{
    json: {
      is_valid: false,
      error_code: 'VALIDATION_ERROR',
      message: `Invalid source '${source}'. Allowed values: ${Array.from(ALLOWED_SOURCES).join(', ')}.`,
      event_id: null
    }
  }];
}

// 3. Validate severity if provided
const severity = input.severity || null;
if (severity && !ALLOWED_SEVERITIES.has(severity)) {
  return [{
    json: {
      is_valid: false,
      error_code: 'VALIDATION_ERROR',
      message: `Invalid severity '${severity}'. Allowed values: ${Array.from(ALLOWED_SEVERITIES).join(', ')}.`,
      event_id: null
    }
  }];
}

// 4. Validate category/department if provided
const category = input.category || input.department || null;
if (category && !ALLOWED_DEPARTMENTS.has(category)) {
  return [{
    json: {
      is_valid: false,
      error_code: 'VALIDATION_ERROR',
      message: `Invalid category/department '${category}'. Allowed values: ${Array.from(ALLOWED_DEPARTMENTS).join(', ')}.`,
      event_id: null
    }
  }];
}

// Generate or retain UUID identifiers
function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const event_id = input.event_id || uuidv4();
const complaint_id = input.complaint_id || null;
const agent_run_id = uuidv4();

// Location handling
const location = input.location || {
  latitude: input.latitude !== undefined ? input.latitude : null,
  longitude: input.longitude !== undefined ? input.longitude : null,
  location_text: input.location_text || null
};

// Step 4: Determine relevant departments
const descLower = description.toLowerCase();
const implicated = new Set();

if (category && category !== 'general') {
  implicated.add(category);
}

const keywords = {
  traffic: ['traffic', 'congestion', 'traffic jam', 'signals', 'signal', 'road blockage', 'blocked road', 'gridlock'],
  safety: ['hazard', 'threat', 'danger', 'fire', 'accident', 'emergency', 'collapse', 'structural damage'],
  waste: ['garbage', 'trash', 'overflowing bin', 'waste', 'litter', 'dump', 'debris', 'sanitation'],
  environment: ['aqi', 'air quality', 'smog', 'pollution', 'toxic fumes', 'smoke', 'chemical odor'],
  water: ['waterlogging', 'water leak', 'pipeline burst', 'flooding', 'sewage', 'drainage', 'water supply'],
  energy: ['power outage', 'blackout', 'street light', 'wire hanging', 'transformer', 'electricity', 'pole sparked']
};

for (const [dept, terms] of Object.entries(keywords)) {
  for (const term of terms) {
    if (descLower.includes(term)) {
      implicated.add(dept);
      break;
    }
  }
}

let departments = Array.from(implicated);
let routing_reason = '';

if (departments.length === 0) {
  departments = ['general'];
  routing_reason = 'Category is unspecified or ambiguous; no single specialized department clearly matches.';
} else if (departments.length > 1) {
  routing_reason = `Cross-department coordination required: incident implicates ${departments.join(', ')}.`;
} else {
  routing_reason = `Single department identified: ${departments[0]}.`;
}

return [{
  json: {
    is_valid: true,
    event_id,
    complaint_id,
    agent_run_id,
    source,
    description,
    category,
    severity,
    location,
    context: input.context || {},
    departments,
    routing_reason
  }
}];

// Format standard validation error (Section 8.3)
const input = $input.first().json;
return [{
  json: {
    success: false,
    error_code: input.error_code || 'VALIDATION_ERROR',
    message: input.message || 'Validation failed.',
    event_id: null
  }
}];

// Format department payload matching Section 3.5
const data = $input.first().json;
const department = data.departments[0];

const deptInput = {
  event_id: data.event_id,
  complaint_id: data.complaint_id,
  source: data.source,
  department: department,
  description: data.description,
  location: data.location,
  severity: data.severity || 'medium',
  context: data.context || {}
};

return [{
  json: {
    ...data,
    primary_department: department,
    dept_input: deptInput
  }
}];

// General or cross-department direct passthrough without specialist workflow
return [{
  json: {
    agent: 'general',
    department: 'general',
    findings: ['Complaint requires general administrative review.'],
    recommendation: 'Conduct human triage.',
    requires_human_approval: true,
    status: 'recommendation_ready'
  }
}];

// Step 7, 8, 9: Consolidate findings, apply priority rules, build output contract
const runData = $('Prepare Department Call').first().json;
const subWorkflowResult = $input.first() ? $input.first().json : null;

const agentResults = [];
if (subWorkflowResult) {
  // Validate if result succeeded or failed
  if (subWorkflowResult.error || subWorkflowResult.errorMessage) {
    agentResults.push({
      department: runData.primary_department,
      status: 'failed',
      error: subWorkflowResult.errorMessage || subWorkflowResult.error || 'Department workflow returned an error.'
    });
  } else {
    agentResults.push(subWorkflowResult);
  }
}

// Section 4.3: Priority Rules
const descLower = runData.description.toLowerCase();
const criticalTriggers = ['immediate threat to life', 'serious danger', 'life-threatening', 'active fire', 'building collapse', 'live high-voltage wire in water', 'electrocution risk'];
const highTriggers = ['severe waterlogging', 'massive traffic jam', 'power outage affecting hospital', 'blocked emergency access', 'toxic leak', 'major road collapse'];
const lowTriggers = ['graffiti', 'cosmetic', 'flickering bulb in daylight', 'minor litter', 'mild annoyance'];

let overallSeverity = 'medium';
let priorityReason = '';

const isInsufficient = runData.description.trim().split(/\s+/).length < 4 && !runData.category;

if (criticalTriggers.some(t => descLower.includes(t))) {
  overallSeverity = 'critical';
  priorityReason = 'Supplied information explicitly indicates an immediate threat to life or serious danger.';
} else if (highTriggers.some(t => descLower.includes(t)) || (agentResults[0] && agentResults[0].severity === 'high')) {
  overallSeverity = 'high';
  priorityReason = 'Significant public safety or infrastructure disruption indicated; timely intervention recommended.';
} else if (isInsufficient || runData.departments[0] === 'general') {
  overallSeverity = 'medium';
  priorityReason = 'Supplied information provides insufficient detail to confirm urgency; severity defaults to medium and requires human verification.';
} else if (lowTriggers.some(t => descLower.includes(t)) || runData.severity === 'low') {
  overallSeverity = 'low';
  priorityReason = 'Minor civic issue with no stated immediate risk to public safety or core infrastructure.';
} else {
  overallSeverity = runData.severity || 'medium';
  priorityReason = `The complaint reports a civic ${runData.departments[0] !== 'general' ? runData.departments[0] : 'general'} issue without a confirmed immediate threat.`;
}

// Consolidated recommendations
const recommendations = [];
const loc = runData.location || {};
if (loc.latitude === null && !loc.location_text) {
  recommendations.push('Request human verification of the reported location as precise coordinates/location text are missing.');
} else {
  recommendations.push('Request human verification of the reported location.');
}

if (runData.departments[0] === 'general') {
  recommendations.push('Conduct human triage to classify the ambiguous complaint into the appropriate municipal department.');
} else {
  for (const dept of runData.departments) {
    const match = agentResults.find(r => r && r.department === dept);
    if (match) {
      if (match.status === 'failed' || match.error) {
        recommendations.push(`Department assessment for ${dept} was unavailable or returned an error; require manual inspection by ${dept} supervisor.`);
      } else if (match.recommendation) {
        recommendations.push(`[${dept.charAt(0).toUpperCase() + dept.slice(1)}] ${match.recommendation}`);
      }
    } else {
      recommendations.push(`Assign the verified complaint to the municipal ${dept} team for operational review.`);
    }
  }
}

const nowIso = new Date().toISOString();

const commandDecision = {
  agent: 'city_command',
  event_id: runData.event_id,
  complaint_id: runData.complaint_id || null,
  overall_severity: overallSeverity,
  priority_reason: priorityReason,
  departments_involved: runData.departments,
  agent_results: agentResults,
  consolidated_recommendations: recommendations,
  requires_human_approval: true,
  status: 'awaiting_human_review',
  created_at: nowIso
};

return [{
  json: commandDecision
}];

// Step 11: Return the exact Command Agent output contract
// Retrieve output from Consolidate Findings & Priority node
const decision = $('Consolidate Findings & Priority').first().json;
return [{
  json: decision
}];
